import math
import numbers


def _is_zero_price(value):
    """True only for a numeric (non-bool) price exactly equal to zero."""
    if isinstance(value, bool) or not isinstance(value, numbers.Number):
        return False
    return value == 0 and not (isinstance(value, float) and math.isnan(value))


def eligible(entries, required_features):
    """Return entries safe for the requested feature set.

    Preserves input order. Keeps only entries that are:
      - enabled,
      - not expired,
      - priced at exactly numeric zero (booleans excluded),
      - containing every required feature.
    """
    required = set(required_features)
    result = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        if not entry.get("enabled", True):
            continue
        if entry.get("expired", False):
            continue
        if "price" not in entry:
            continue
        if not _is_zero_price(entry["price"]):
            continue
        features = set(entry.get("features") or ())
        if not required.issubset(features):
            continue
        result.append(entry)
    return result

